// COSGRAL W3-BE7: builds the phone web app's files into src/backend/mobile-app-assets.ts, so the phone server can serve
// them from memory in the packaged program (no files next to the executable, no new dependency). The script is
// TypeScript → JavaScript with the compiler that is already a dev dependency. Run `bun run build:mobile-app` after
// changing anything in src/mobile-app; a test fails when the generated file is out of date.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

export interface MobileAppFile {
  type: string;
  body: string;
}

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCES = join(ROOT, "src", "mobile-app");
const OUTPUT = join(ROOT, "src", "backend", "mobile-app-assets.ts");

const RUNTIME_VALUES = join(ROOT, "packages", "contracts", "src", "runtime-values.ts");
const RUNTIME_VALUES_IMPORT = /^import \{[^}]*\} from "@openbot\/contracts\/runtime-values";\n/m;

function read(name: string): string {
  return readFileSync(join(SOURCES, name), "utf8").replace(/\r\n/g, "\n");
}

/**
 * The page script is one file without a bundler: the small runtime checks it imports from the contracts package
 * (a file with no imports of its own) are copied in where the import was.
 */
function withRuntimeValues(source: string): string {
  if (!RUNTIME_VALUES_IMPORT.test(source)) return source;
  const helpers = readFileSync(RUNTIME_VALUES, "utf8")
    .replace(/\r\n/g, "\n")
    .replace(/^export /gm, "");
  const combined = source.replace(RUNTIME_VALUES_IMPORT, `${helpers}\n`);
  if (/^import /m.test(combined)) throw new Error("The phone app may import only @openbot/contracts/runtime-values.");
  return combined;
}

/** The files of the app by the path a phone asks for. */
export function buildMobileAppAssets(): Record<string, MobileAppFile> {
  const script = ts
    .transpileModule(withRuntimeValues(read("app.ts")), {
      compilerOptions: {
        target: ts.ScriptTarget.ES2022,
        module: ts.ModuleKind.ESNext,
        newLine: ts.NewLineKind.LineFeed,
      },
    })
    .outputText.replace(/\nexport \{\};\n?$/, "\n");
  const html = read("index.html");
  const css = read("app.css");
  const manifest = read("manifest.webmanifest");
  const icon = read("icon.svg");
  const version = createHash("sha256")
    .update([html, script, css, manifest, icon].join("\u0000"))
    .digest("hex")
    .slice(0, 12);
  return {
    "/app/": { type: "text/html; charset=utf-8", body: html },
    "/app/app.js": { type: "text/javascript; charset=utf-8", body: script },
    "/app/app.css": { type: "text/css; charset=utf-8", body: css },
    "/app/manifest.webmanifest": { type: "application/manifest+json; charset=utf-8", body: manifest },
    "/app/icon.svg": { type: "image/svg+xml; charset=utf-8", body: icon },
    "/app/sw.js": { type: "text/javascript; charset=utf-8", body: read("sw.js").replace("__VERSION__", version) },
  };
}

export function renderMobileAppAssetsModule(files: Record<string, MobileAppFile>): string {
  const entries = Object.entries(files)
    .map(
      ([path, file]) =>
        `  ${JSON.stringify(path)}: { type: ${JSON.stringify(file.type)}, body: ${JSON.stringify(file.body)} },`,
    )
    .join("\n");
  return [
    "// biome-ignore-all lint: generated file",
    "// biome-ignore-all format: generated file",
    "// Generated by scripts/build-mobile-app.ts from src/mobile-app. Do not edit; run `bun run build:mobile-app`.",
    "",
    "export const MOBILE_APP_FILES: Record<string, { type: string; body: string }> = {",
    entries,
    "};",
    "",
  ].join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUTPUT, renderMobileAppAssetsModule(buildMobileAppAssets()), "utf8");
  console.log(`Wrote ${OUTPUT}`);
}
